/**
 * Description links: data/description-links.json (and the workbook data/description-links.xlsx the site owner opens),
 * generated by scripts/build_description_links.py. One line for every mapped YouTube video, in the video's own language,
 * and one for every podcast episode, each linking to that sage's page; the owner pastes them at the top of the
 * descriptions. A line that links a video to the wrong sage or the wrong language, or that says something the page does
 * not have, sends a viewer to the wrong place, so the rules are checked here against the sources, not against the script:
 *
 *   - which video is which sage: data/youtube-sage-map.json (hand-checked, by playlist row) and its `_left_out`;
 *     the video's id and language: data/youtube-playlist.tsv (the language is the video's own `defaultLanguage`);
 *   - what a sage's page has in a language: the research files, public/data-quiz.json, and the teacher / student links
 *     of the corpus the app serves (lib/serverData.ts, read through getSageConnections, not the script's own walk);
 *   - the names: lib/displayName.ts over the roster label or the overlay label, with gershayim.
 *
 * The rules are one function over a document (descriptionProblems). It runs on the real file and, in the same file, on
 * copies broken on purpose, each rule shown to fire. The workbook is read by hand (a zip and its XML: no library) and
 * compared with the JSON, so the file the owner opens is the file that is tested. Nothing here names a sage id.
 */
import assert from 'node:assert/strict'
import fs from 'node:fs'
import path from 'node:path'
import zlib from 'node:zlib'
import graph from '../public/data.json'
import { getAllSages, getSageConnections } from '../lib/serverData'
import { localizeSage } from '../lib/serverDataTranslator'
import { labelParts } from '../lib/displayName'
import { hasQuiz } from '../lib/quiz'
import { sageVideos } from '../lib/youtube'
import { SITE_URL } from '../lib/siteUrl'

let passed = 0
let failed = 0
function test(name: string, fn: () => void) {
  try {
    fn()
    console.log(`  ok  ${name}`)
    passed++
  } catch (e) {
    console.log(`  FAIL ${name}`)
    console.log(`       ${(e as Error).message}`)
    failed++
  }
}

type Lang = 'he' | 'en' | 'ru'
const LANGS: Lang[] = ['he', 'en', 'ru']
interface Claims { kind: 'm' | 'f' | 'n'; research: boolean; quiz: boolean; teachers: boolean; students: boolean }
interface YtEntry { row: number; id: string; lang: Lang; sage: string; label: string; name: string; title: string; claims: Claims; line: string }
interface SpEntry { sage: string; label: string; name: string; episode: string; claims: Claims; line: string }
interface Unresolved { sage: string; label: string; link: string }
interface Doc { site: string; youtube: YtEntry[]; spotify: SpEntry[]; unresolved: Unresolved[] }

const REPO = path.join(__dirname, '..', '..')
const PUBLIC = path.join(__dirname, '..', 'public')
const JSON_FILE = path.join(REPO, 'data', 'description-links.json')
const XLSX_FILE = path.join(REPO, 'data', 'description-links.xlsx')
const LINE_LIMIT = 200
const HEBREW = /[֐-׿]/
const CYRILLIC = /[Ѐ-ӿ]/

// ---- the sources -------------------------------------------------------------------------------------------
const playlist = new Map<number, { id: string; lang: Lang; title: string }>()
for (const l of fs.readFileSync(path.join(REPO, 'data', 'youtube-playlist.tsv'), 'utf8').split('\n')) {
  if (!l.trim()) continue
  const [n, id, , lang, title] = l.split('\t')
  playlist.set(Number(n), { id, lang: lang as Lang, title })
}
const mapFile = JSON.parse(fs.readFileSync(path.join(REPO, 'data', 'youtube-sage-map.json'), 'utf8')) as {
  sages: Record<string, number[]>
  _left_out: Record<string, string>
}
const owner = new Map<number, string>()
for (const [sid, rows] of Object.entries(mapFile.sages)) for (const r of rows) owner.set(r, sid)
const leftOut = new Set<number>()
for (const key of Object.keys(mapFile._left_out)) {
  for (const part of key.split(',')) {
    const [a, b] = part.split('-').map(Number)
    for (let r = a; r <= (b ?? a); r++) leftOut.add(r)
  }
}
const roster = new Map((graph.nodes as Array<{ id: string; label: string; chapter_type?: string; spotify_url?: string }>).map(n => [n.id, n]))
const sages = new Map(getAllSages().map(s => [s.id, s]))
// An entry that is a book, a group or a topic: no possessive, no teachers or students (as in rebuild_data_from_csv.py).
const NOT_A_PERSON = new Set(['נושא/מושג', 'נושא', 'ספר', 'חיבור', 'אירוע היסטורי', 'דמויות', 'מחזור ויטרי', 'מדרש רבה'])
// Six women the roster left without the 'נשים' tag until 2026-10-25, by name: ids drift, names do not.
const WOMEN_ONCE_UNTAGGED = ['הרבנית חיה מושקא שניאורסון', 'גאולה כהן', 'לאה אמנו', "סוליקא חג'ואל", 'אימא שלום', 'מרים הנביאה']

const researchExists = (id: string, lang: Lang): boolean => {
  const p = path.join(PUBLIC, 'research', lang === 'he' ? `${id}.json` : `${id}.${lang}.json`)
  if (!fs.existsSync(p)) return false
  const docs = JSON.parse(fs.readFileSync(p, 'utf8')) as Array<{ content?: string }>
  return Array.isArray(docs) && docs.some(d => String(d.content ?? '').trim() !== '')
}
const quizExists = (id: string, lang: Lang): boolean =>
  hasQuiz(id, lang) && fs.existsSync(path.join(PUBLIC, 'quiz', lang === 'he' ? `${id}.json` : `${id}.${lang}.json`))

function factsOf(id: string, lang: Lang): Claims {
  const node = roster.get(id)!
  const person = !NOT_A_PERSON.has(node.chapter_type ?? '') && !NOT_A_PERSON.has(node.label)
  const woman = !!sages.get(id)!.tags?.includes('נשים')
  const links = getSageConnections(id).filter(c => c.source !== c.target)
  // `teacher`: the source teaches the target; `student`: the source is the student of the target
  const asTeacher = (c: (typeof links)[number]) => (c.type === 'teacher' && c.source === id) || (c.type === 'student' && c.target === id)
  const asStudent = (c: (typeof links)[number]) => (c.type === 'teacher' && c.target === id) || (c.type === 'student' && c.source === id)
  return {
    kind: !person ? 'n' : woman ? 'f' : 'm',
    research: researchExists(id, lang),
    quiz: quizExists(id, lang),
    teachers: person && links.some(asStudent),   // he has teachers when he is somebody's student
    students: person && links.some(asTeacher),
  }
}

function nameOf(id: string, lang: Lang): string {
  const sage = sages.get(id)!
  const name = labelParts(lang === 'he' ? sage.label : localizeSage(sage, lang).label).name
  return lang === 'he' ? name.replace(/(?<=[א-ת])"(?=[א-ת])/g, '״').replace(/(?<=[א-ת])'/g, '׳') : name
}

// ---- the wording each line may use (closed vocabularies: nothing else is claimed) ---------------------------------
const SHAPE: Record<Lang, RegExp> = {
  he: /^📜 (.+?) באוצר חכמים — (.+): (https:\/\/\S+)$/,
  en: /^📜 (.+?) on Ozar Chachamim — (.+): (https:\/\/\S+)$/,
  ru: /^📜 (.+?) в «Оцар Хахамим» — (.+): (https:\/\/\S+)$/,
}
const VOCAB: Record<Lang, string[]> = {
  he: ['המחקר', 'המלא', 'הדף', 'שלו', 'שלה', 'חידון', 'רבותיו', 'רבותיה', 'תלמידיו', 'תלמידיה'],
  en: ['the', 'full', 'research', 'his', 'her', 'page', 'a', 'quiz', 'teachers', 'students', 'and'],
  ru: ['полное', 'исследование', 'его', 'её', 'страница', 'викторина', 'учителя', 'ученики', 'и', 'а', 'также'],
}
const MALE: Record<Lang, string[]> = { he: ['שלו', 'רבותיו', 'תלמידיו'], en: ['his'], ru: ['его'] }
const FEMALE: Record<Lang, string[]> = { he: ['שלה', 'רבותיה', 'תלמידיה'], en: ['her'], ru: ['её'] }
const WORD: Record<Lang, { research: string; page: string; quiz: string; teachers: string[]; students: string[] }> = {
  he: { research: 'המחקר', page: 'הדף', quiz: 'חידון', teachers: ['רבותיו', 'רבותיה'], students: ['תלמידיו', 'תלמידיה'] },
  en: { research: 'research', page: 'page', quiz: 'quiz', teachers: ['teachers'], students: ['students'] },
  ru: { research: 'исследование', page: 'страница', quiz: 'викторина', teachers: ['учителя'], students: ['ученики'] },
}

function tokensOf(lang: Lang, parts: string): string[] {
  const vocab = new Set(VOCAB[lang])
  return parts.split(/[\s,]+/).filter(Boolean).map(t => (lang === 'he' && !vocab.has(t) && t.startsWith('ו') ? t.slice(1) : t))
}

// ---- the rules ---------------------------------------------------------------------------------------------
interface Line { lang: Lang; sage: string; label: string; name: string; claims: Claims; line: string; url: string; where: string }

function lineProblems(e: Line): string[] {
  const out: string[] = []
  const p = (msg: string) => out.push(`${e.where}: ${msg}`)
  const m = SHAPE[e.lang].exec(e.line)
  if (!m) return [`${e.where}: the line does not have the shape "📜 name — parts: url": ${e.line}`]
  const [, name, parts, url] = m
  if (url !== e.url) p(`the url is ${url}, expected ${e.url}`)
  if ((e.line.match(/https?:\/\//g) ?? []).length !== 1) p('the line must hold exactly one address')
  if (e.line.length >= LINE_LIMIT) p(`${e.line.length} characters (limit ${LINE_LIMIT - 1})`)
  // the language of the line is the language of the video
  if (e.lang === 'he' && (!HEBREW.test(e.line) || CYRILLIC.test(e.line))) p('a Hebrew line must be Hebrew, with no Cyrillic')
  if (e.lang === 'en' && (HEBREW.test(e.line) || CYRILLIC.test(e.line))) p('an English line must hold no Hebrew or Cyrillic')
  if (e.lang === 'ru' && (!CYRILLIC.test(e.line) || HEBREW.test(e.line))) p('a Russian line must be Cyrillic, with no Hebrew')
  if (e.lang === 'he' && /[א-ת]["']|["'][א-ת]/.test(e.line)) p('Hebrew with an ASCII quote beside a letter: gershayim (״) and geresh (׳)')
  // the name
  const expected = nameOf(e.sage, e.lang)
  if (name !== expected && name !== expected.replace(/\s*\([^)]*\)\s*$/, '').trim()) p(`the name is "${name}", the page's is "${expected}"`)
  if (e.name !== name) p(`the stored name "${e.name}" is not the one in the line`)
  // the claims: each optional part is there exactly when it is true for this sage in this language
  const truth = factsOf(e.sage, e.lang)
  if (JSON.stringify(e.claims) !== JSON.stringify(truth)) p(`claims ${JSON.stringify(e.claims)} but the corpus says ${JSON.stringify(truth)}`)
  const words = tokensOf(e.lang, parts)
  const vocab = new Set(VOCAB[e.lang])
  const stray = words.filter(w => !vocab.has(w))
  if (stray.length) p(`says something beyond the five facts: ${stray.join(' ')}`)
  const has = (list: string[]) => list.some(w => words.includes(w))
  const w = WORD[e.lang]
  const says = {
    research: words.includes(w.research),
    page: words.includes(w.page),
    quiz: words.includes(w.quiz),
    teachers: has(w.teachers),
    students: has(w.students),
  }
  if (says.research !== truth.research) p(truth.research ? 'the sage has research in this language and the line does not say so' : 'the line says "the full research" but there is none in this language')
  if (says.page === says.research) p('the line must say either "the full research" or "his page"')
  if (says.quiz !== truth.quiz) p(truth.quiz ? 'the sage has a quiz in this language and the line does not say so' : 'the line says there is a quiz but there is none in this language')
  if (says.teachers !== truth.teachers) p(truth.teachers ? 'the sage has teachers and the line does not say so' : 'the line claims teachers the corpus does not give him')
  if (says.students !== truth.students) p(truth.students ? 'the sage has students and the line does not say so' : 'the line claims students the corpus does not give him')
  // grammatical gender follows the sage (a book or a topic takes no possessive)
  const male = has(MALE[e.lang])
  const female = has(FEMALE[e.lang])
  if (truth.kind === 'f' && male) p('a woman, and the line speaks of "his"')
  if (truth.kind === 'm' && female) p('a man, and the line speaks of "her"')
  if (truth.kind === 'n' && (male || female)) p('a book or a topic, and the line has a possessive')
  if (truth.kind !== 'n' && (says.page || says.teachers || says.students) && !male && !female) p('a person, and the line has no possessive')
  return out
}

function descriptionProblems(doc: Doc): string[] {
  const out: string[] = []
  const site = SITE_URL
  if (doc.site !== site) out.push(`site: the lines point at ${doc.site}, the app's address is ${site}: regenerate with scripts/build_description_links.py`)
  // ---- YouTube: every mapped row, once, in the video's own language, at the sage the map gives ----
  const seen = new Map<number, number>()
  for (const e of doc.youtube) seen.set(e.row, (seen.get(e.row) ?? 0) + 1)
  for (const [row, who] of owner) if (!seen.has(row)) out.push(`row ${row} (sage ${who}) has no line`)
  for (const [row, n] of seen) {
    if (n > 1) out.push(`row ${row} appears ${n} times`)
    if (leftOut.has(row)) out.push(`row ${row} is in _left_out of the map and must not have a line`)
    else if (!owner.has(row)) out.push(`row ${row} is not mapped to any sage`)
  }
  for (const e of doc.youtube) {
    const where = `YouTube row ${e.row}`
    const v = playlist.get(e.row)
    if (!v) { out.push(`${where}: not in the playlist snapshot`); continue }
    if (e.id !== v.id) out.push(`${where}: the video is ${e.id}, the playlist row is ${v.id}`)
    if (e.lang !== v.lang) out.push(`${where}: language ${e.lang}, the video's own is ${v.lang}`)
    if (e.title !== v.title) out.push(`${where}: the title differs from the playlist's`)
    if (e.sage !== owner.get(e.row)) out.push(`${where}: sage ${e.sage}, the map says ${owner.get(e.row)}`)
    const node = roster.get(e.sage)
    if (!node) { out.push(`${where}: sage ${e.sage} is not on the roster`); continue }
    if (e.label !== node.label) out.push(`${where}: sage ${e.sage} was "${e.label}", the roster now says "${node.label}"`)
    // the address names this sage and this language (the id inside the line is the one the map gave)
    const url = `${site}/${v.lang}/sage/${owner.get(e.row)}?utm_source=youtube&utm_medium=video`
    out.push(...lineProblems({ ...e, lang: v.lang, sage: owner.get(e.row) ?? e.sage, url, where }))
    if (!e.line.includes(`/${v.lang}/sage/${owner.get(e.row)}?`)) out.push(`${where}: the line does not link to /${v.lang}/sage/${owner.get(e.row)}`)
    // the page the line leads to shows this very video (public/data-youtube.json, what the site embeds)
    if (!sageVideos(owner.get(e.row) ?? e.sage, v.lang).some(x => x.id === v.id)) out.push(`${where}: the page /${v.lang}/sage/${owner.get(e.row)} does not show the video ${v.id}`)
  }
  // ---- Spotify: every episode address, Hebrew, once; the links that are not episodes have no line ----
  const episodes = new Map<string, string>()
  const unresolved = new Map<string, string>()
  for (const [id, n] of roster) {
    const u = (n.spotify_url ?? '').trim()
    const m = /^https:\/\/open\.spotify\.com\/episode\/([A-Za-z0-9]+)/.exec(u)
    if (m) episodes.set(id, `https://open.spotify.com/episode/${m[1]}`)
    else if (u) unresolved.set(id, u)
  }
  const sp = new Map<string, number>()
  for (const e of doc.spotify) sp.set(e.sage, (sp.get(e.sage) ?? 0) + 1)
  for (const id of episodes.keys()) if (!sp.has(id)) out.push(`Spotify: sage ${id} has an episode and no line`)
  for (const [id, n] of sp) {
    if (n > 1) out.push(`Spotify: sage ${id} appears ${n} times`)
    if (!episodes.has(id)) out.push(`Spotify: sage ${id} has no episode address on the roster but has a line`)
  }
  for (const e of doc.spotify) {
    const where = `Spotify sage ${e.sage}`
    const node = roster.get(e.sage)
    if (!node) { out.push(`${where}: not on the roster`); continue }
    if (e.label !== node.label) out.push(`${where}: was "${e.label}", the roster now says "${node.label}"`)
    if (e.episode !== episodes.get(e.sage)) out.push(`${where}: the episode is ${e.episode}, the roster says ${episodes.get(e.sage)}`)
    out.push(...lineProblems({ ...e, lang: 'he', url: `${site}/he/sage/${e.sage}?utm_source=spotify&utm_medium=podcast`, where }))
  }
  const listed = new Map(doc.unresolved.map(u => [u.sage, u]))
  for (const [id, u] of unresolved) {
    const l = listed.get(id)
    if (!l) out.push(`Spotify: sage ${id} (${u}) is not listed among the links that do not open`)
    else if (l.link !== u || l.label !== roster.get(id)!.label) out.push(`Spotify: the unresolved entry of ${id} differs from the roster`)
    if (sp.has(id)) out.push(`Spotify: sage ${id} has a link that is not an episode address and must have no line`)
  }
  for (const id of listed.keys()) if (!unresolved.has(id)) out.push(`Spotify: sage ${id} is listed as unresolved but the roster has an episode or nothing`)
  return out
}

// ---- the workbook, read without a library ------------------------------------------------------------------
function unzip(buf: Buffer): Map<string, Buffer> {
  let eocd = buf.length - 22
  while (eocd >= 0 && buf.readUInt32LE(eocd) !== 0x06054b50) eocd--
  assert.ok(eocd >= 0, 'not a zip file')
  const count = buf.readUInt16LE(eocd + 10)
  let at = buf.readUInt32LE(eocd + 16)
  const files = new Map<string, Buffer>()
  for (let i = 0; i < count; i++) {
    assert.equal(buf.readUInt32LE(at), 0x02014b50, 'bad central directory')
    const method = buf.readUInt16LE(at + 10)
    const size = buf.readUInt32LE(at + 20)
    const nameLen = buf.readUInt16LE(at + 28)
    const extraLen = buf.readUInt16LE(at + 30)
    const commentLen = buf.readUInt16LE(at + 32)
    const local = buf.readUInt32LE(at + 42)
    const name = buf.toString('utf8', at + 46, at + 46 + nameLen)
    const dataAt = local + 30 + buf.readUInt16LE(local + 26) + buf.readUInt16LE(local + 28)
    const raw = buf.subarray(dataAt, dataAt + size)
    files.set(name, method === 0 ? raw : zlib.inflateRawSync(raw))
    at += 46 + nameLen + extraLen + commentLen
  }
  return files
}

const unescapeXml = (s: string) =>
  s.replace(/&#x([0-9a-fA-F]+);/g, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, '&')

type Cell = string | number
interface Sheet { name: string; xml: string; rows: Map<number, Map<string, Cell>> }

function readWorkbook(file: string): Sheet[] {
  const zip = unzip(fs.readFileSync(file))
  const text = (n: string) => {
    const b = zip.get(n)
    assert.ok(b, `${n} is missing from the workbook`)
    return b.toString('utf8')
  }
  const shared: string[] = []
  if (zip.has('xl/sharedStrings.xml')) {
    for (const si of text('xl/sharedStrings.xml').match(/<si>[\s\S]*?<\/si>|<si\/>/g) ?? []) {
      shared.push(unescapeXml([...si.matchAll(/<t(?:\s[^>]*)?>([\s\S]*?)<\/t>/g)].map(m => m[1]).join('')))
    }
  }
  const rels = new Map<string, string>()
  for (const m of text('xl/_rels/workbook.xml.rels').matchAll(/<Relationship\b[^>]*>/g)) {
    const id = /\bId="([^"]+)"/.exec(m[0])?.[1]
    const target = /\bTarget="([^"]+)"/.exec(m[0])?.[1]
    if (id && target) rels.set(id, target.replace(/^\/?(xl\/)?/, 'xl/'))
  }
  const sheets: Sheet[] = []
  for (const m of text('xl/workbook.xml').matchAll(/<sheet\b[^>]*>/g)) {
    const name = unescapeXml(/\bname="([^"]*)"/.exec(m[0])![1])
    const rid = /\br:id="([^"]+)"/.exec(m[0])![1]
    const xml = text(rels.get(rid)!)
    const rows = new Map<number, Map<string, Cell>>()
    for (const c of xml.matchAll(/<c\b([^>]*?)(?:\/>|>([\s\S]*?)<\/c>)/g)) {
      const ref = /\br="([A-Z]+)(\d+)"/.exec(c[1])!
      const type = /\bt="([^"]+)"/.exec(c[1])?.[1]
      const body = c[2] ?? ''
      let value: Cell | undefined
      if (type === 'inlineStr') value = unescapeXml([...body.matchAll(/<t(?:\s[^>]*)?>([\s\S]*?)<\/t>/g)].map(x => x[1]).join(''))
      else {
        const v = /<v>([\s\S]*?)<\/v>/.exec(body)?.[1]
        if (v === undefined) continue
        value = type === 's' ? shared[Number(v)] : type === 'str' ? unescapeXml(v) : Number(v)
      }
      const r = Number(ref[2])
      if (!rows.has(r)) rows.set(r, new Map())
      rows.get(r)!.set(ref[1], value)
    }
    sheets.push({ name, xml, rows })
  }
  return sheets
}

// ---- run ---------------------------------------------------------------------------------------------------
const doc = JSON.parse(fs.readFileSync(JSON_FILE, 'utf8')) as Doc
const clone = (): Doc => JSON.parse(JSON.stringify(doc)) as Doc

console.log('\ndata/description-links.json')

test('the file is there and holds the lines, the videos and the episodes', () => {
  assert.ok(doc.youtube.length >= 700, `only ${doc.youtube.length} videos`)
  assert.ok(doc.spotify.length >= 400, `only ${doc.spotify.length} episodes`)
  assert.equal(doc.youtube.length, owner.size, 'one line per mapped video')
})

test('every mapped video has one line, in its own language, at the sage the map gives; no left-out row; every claim is true', () => {
  assert.deepEqual(descriptionProblems(doc), [], 'regenerate with scripts/build_description_links.py (or fix the map)')
})

test('every row of the map is a row of the playlist snapshot, and every playlist row is mapped or left out', () => {
  for (const row of owner.keys()) assert.ok(playlist.has(row), `row ${row} is not in the snapshot`)
  const loose = [...playlist.keys()].filter(r => !owner.has(r) && !leftOut.has(r))
  assert.deepEqual(loose, [], 'rows neither mapped nor left out')
  assert.deepEqual([...owner.keys()].filter(r => leftOut.has(r)), [], 'rows both mapped and left out')
})

test('the three languages are all there, and each sage kind (man, woman, book or topic) has lines', () => {
  for (const lang of LANGS.filter(l => l !== 'he')) assert.ok(doc.youtube.some(e => e.lang === lang), `no ${lang} video`)
  assert.ok(doc.youtube.some(e => e.lang === 'he'), 'no Hebrew video')
  for (const kind of ['m', 'f', 'n'] as const) assert.ok(doc.youtube.some(e => e.claims.kind === kind), `no ${kind} line`)
  assert.ok(doc.youtube.some(e => !e.claims.research) && doc.youtube.some(e => e.claims.quiz) && doc.youtube.some(e => e.claims.teachers && !e.claims.students))
})

test('the tag alone decides who is a woman: the six once left untagged carry it now, and their lines are a woman\'s', () => {
  const idOf = new Map([...roster.values()].map(n => [n.label, n.id]))
  for (const label of WOMEN_ONCE_UNTAGGED) {
    const id = idOf.get(label)
    assert.ok(id, `"${label}" is not a roster label any more`)
    assert.ok(sages.get(id)!.tags?.includes('נשים'), `${id} ${label} lacks the 'נשים' tag`)
    for (const e of [...doc.youtube, ...doc.spotify].filter(x => x.sage === id)) assert.equal(e.claims.kind, 'f', `${id} ${label}: a line that does not take her for a woman`)
  }
  const tagged = getAllSages().filter(s => s.tags?.includes('נשים'))
  assert.ok(tagged.length >= 25, `only ${tagged.length} tagged women`)
})

test('the names are the pages\' names: no subtitle, no years, proper gershayim', () => {
  for (const e of doc.youtube) {
    assert.ok(!/ [–—-] /.test(e.name), `${e.row}: "${e.name}" still has a subtitle`)
  }
  const he = doc.spotify.map(e => e.name).concat(doc.youtube.filter(e => e.lang === 'he').map(e => e.name))
  assert.ok(he.some(n => n.includes('״')), 'no name with a gershayim at all')
  assert.deepEqual(he.filter(n => /[א-ת]"[א-ת]/.test(n)), [], 'names with an ASCII quote inside a word')
})

console.log('\neach rule fires on a line broken on purpose')

function expectProblem(label: string, mutate: (d: Doc) => void, pattern: RegExp) {
  test(label, () => {
    const d = clone()
    mutate(d)
    const problems = descriptionProblems(d)
    assert.ok(problems.some(p => pattern.test(p)), `no problem matched ${pattern}; got: ${problems.slice(0, 4).join(' | ') || 'none'}`)
  })
}
const first = <T,>(list: T[], pred: (x: T) => boolean): T => {
  const x = list.find(pred)
  assert.ok(x, 'no entry to break')
  return x
}
const other = (id: string) => [...roster.keys()].find(k => k !== id)!

expectProblem('a video linked to another sage',
  d => { const e = first(d.youtube, x => x.lang === 'en'); e.line = e.line.replace(`/sage/${e.sage}?`, `/sage/${other(e.sage)}?`) },
  /url is|does not link to/)
expectProblem('a video linked to the page of another language',
  d => { const e = first(d.youtube, x => x.lang === 'ru'); e.line = e.line.replace('/ru/sage/', '/en/sage/') },
  /url is|does not link to/)
expectProblem('a video stored under another language than its own',
  d => { const e = first(d.youtube, x => x.lang === 'ru'); e.lang = 'en' },
  /language en, the video's own is ru/)
expectProblem('a video assigned to another sage than the map says',
  d => { const e = first(d.youtube, () => true); e.sage = other(e.sage) },
  /the map says/)
expectProblem('a sage whose id now carries another label',
  d => { first(d.youtube, () => true).label = 'מישהו אחר' },
  /roster now says/)
expectProblem('a mapped video with no line', d => { d.youtube.shift() }, /has no line/)
expectProblem('a video listed twice', d => { d.youtube.push({ ...d.youtube[0] }) }, /appears 2 times/)
expectProblem('a left-out row given a line',
  d => { const row = [...leftOut][0]; d.youtube.push({ ...d.youtube[0], row }) },
  /_left_out/)
expectProblem('a quiz claimed for a sage who has none in that language',
  d => {
    const e = first(d.youtube, x => x.lang === 'en' && !x.claims.quiz && x.claims.research)
    e.line = e.line.replace('the full research', 'the full research and a quiz')
  },
  /there is a quiz but there is none/)
expectProblem('research claimed where the sage has none in that language',
  d => {
    const e = first(d.youtube, x => x.lang === 'en' && !x.claims.research && x.claims.kind === 'm')
    e.line = e.line.replace('his page', 'the full research')
  },
  /there is none in this language/)
expectProblem('teachers and students claimed for a sage with neither',
  d => {
    const e = first(d.youtube, x => x.lang === 'ru' && x.claims.kind === 'm' && !x.claims.teachers && !x.claims.students)
    e.line = e.line.replace(': https', ', а также его учителя и ученики: https')
  },
  /claims (teachers|students)|beyond the five facts|corpus says/)
expectProblem('students claimed for a sage who has only teachers',
  d => {
    const e = first(d.youtube, x => x.lang === 'en' && x.claims.teachers && !x.claims.students)
    e.line = e.line.replace('his teachers', 'his teachers and students')
  },
  /claims students/)
expectProblem('a woman spoken of as "his"',
  d => {
    const e = first(d.youtube, x => x.lang === 'en' && x.claims.kind === 'f' && x.claims.teachers)
    e.line = e.line.replace('her teachers', 'his teachers')
  },
  /a woman, and the line speaks of "his"/)
expectProblem('a man spoken of as "her"',
  d => {
    const e = first(d.youtube, x => x.lang === 'ru' && x.claims.kind === 'm' && x.claims.teachers)
    e.line = e.line.replace(' его ', ' её ')
  },
  /a man, and the line speaks of "her"/)
expectProblem('a possessive on a book or a topic',
  d => {
    const e = first(d.youtube, x => x.lang === 'en' && x.claims.kind === 'n' && !x.claims.research)
    e.line = e.line.replace('the page', 'his page')
  },
  /a book or a topic, and the line has a possessive/)
expectProblem('a Hebrew name with an ASCII quote inside the acronym',
  d => {
    const e = first(d.spotify, x => /״/.test(x.line))
    e.line = e.line.replace('״', '"')
  },
  /ASCII quote/)
expectProblem('a line of 200 characters',
  d => { const e = first(d.youtube, () => true); e.line = e.line.replace(': https', ' ' + 'x'.repeat(LINE_LIMIT) + ': https') },
  /characters \(limit/)
expectProblem('an invented claim',
  d => { const e = first(d.youtube, x => x.lang === 'en'); e.line = e.line.replace(' — ', ' — a free course, ') },
  /beyond the five facts/)
expectProblem('a Spotify line in English', d => { first(d.spotify, () => true).line = '📜 Rashi on Ozar Chachamim — his page: https://x' }, /shape/)
expectProblem('an episode address that is not the roster\'s',
  d => { first(d.spotify, () => true).episode = 'https://open.spotify.com/episode/0000000000000000000000' },
  /the roster says/)
expectProblem('a Spotify line for a link that is not an episode address',
  d => { const u = d.unresolved[0]; d.spotify.push({ ...d.spotify[0], sage: u.sage, label: u.label }) },
  /must have no line|has no episode address/)
expectProblem('an unresolved link that went missing from the list', d => { d.unresolved.pop() }, /is not listed among the links that do not open/)
expectProblem('lines pointing at another site', d => { d.site = 'https://example.org' }, /point at/)

