const sheets = readWorkbook(XLSX_FILE)
const sheet = (name: string) => sheets.find(s => s.name === name)!
const cellsOf = (s: Sheet, from = 2) => [...s.rows.entries()].filter(([r]) => r >= from).sort((a, b) => a[0] - b[0])

test('three sheets, Hebrew names, right to left, header row frozen', () => {
  assert.deepEqual(sheets.map(s => s.name), ['יוטיוב', 'ספוטיפיי', 'הוראות'])
  for (const s of sheets) assert.match(s.xml, /rightToLeft="1"/, `${s.name} is not right to left`)
  for (const name of ['יוטיוב', 'ספוטיפיי']) {
    assert.match(sheet(name).xml, /<pane\b[^>]*ySplit="1"[^>]*state="frozen"|<pane\b[^>]*state="frozen"[^>]*ySplit="1"/, `${name}: the header row is not frozen`)
  }
})

test('the YouTube sheet holds exactly the videos of the JSON, with the same lines, edit links and video links', () => {
  const rows = cellsOf(sheet('יוטיוב')).filter(([, c]) => typeof c.get('I') === 'number')
  assert.equal(rows.length, doc.youtube.length)
  const byRow = new Map(doc.youtube.map(e => [e.row, e]))
  const names: Record<Lang, string> = { he: 'עברית', en: 'English', ru: 'Русский' }
  for (const [r, c] of rows) {
    const e = byRow.get(c.get('I') as number)
    assert.ok(e, `sheet row ${r}: playlist row ${c.get('I')} is not in the JSON`)
    assert.equal(c.get('G'), e.line, `sheet row ${r}: the line differs from the JSON`)
    assert.equal(c.get('F'), `https://studio.youtube.com/video/${e.id}/edit`, `sheet row ${r}: edit link`)
    assert.equal(c.get('H'), `https://youtu.be/${e.id}`, `sheet row ${r}: video link`)
    assert.equal(c.get('D'), e.label, `sheet row ${r}: the sage`)
    assert.equal(c.get('C'), names[e.lang], `sheet row ${r}: the language`)
    assert.equal(c.get('E'), e.title, `sheet row ${r}: the title`)
  }
  assert.equal(new Set(rows.map(([, c]) => c.get('I'))).size, rows.length, 'a video twice in the sheet')
})

test('the YouTube sheet is sorted by views, most viewed first (or in playlist order when there are none)', () => {
  const rows = cellsOf(sheet('יוטיוב')).filter(([, c]) => typeof c.get('I') === 'number')
  const views = rows.map(([, c]) => c.get('B'))
  const seen = views.filter(v => typeof v === 'number') as number[]
  if (seen.length === 0) {
    const order = rows.map(([, c]) => c.get('I') as number)
    assert.deepEqual(order, [...order].sort((a, b) => a - b), 'no views and not in playlist order')
    return
  }
  assert.equal(seen.length, rows.length, 'views for some videos only')
  for (let i = 1; i < rows.length; i++) {
    const [a, b] = [views[i - 1] as number, views[i] as number]
    assert.ok(a > b || (a === b && (rows[i - 1][1].get('I') as number) < (rows[i][1].get('I') as number)), `row ${i + 1}: ${a} before ${b}`)
  }
})

test('the Spotify sheet holds every episode with the JSON\'s line; the links that do not open are listed apart, with no line', () => {
  const rows = cellsOf(sheet('ספוטיפיי'))
  const titleAt = rows.findIndex(([, c]) => c.get('B') === 'קישורים שלא נפתחים')
  assert.ok(titleAt > 0, 'the block "קישורים שלא נפתחים" is missing')
  const main = rows.slice(0, titleAt).filter(([, c]) => typeof c.get('F') === 'number')
  assert.equal(main.length, doc.spotify.length)
  const byId = new Map(doc.spotify.map(e => [e.sage, e]))
  for (const [r, c] of main) {
    const e = byId.get(String(c.get('F')))
    assert.ok(e, `sheet row ${r}: sage ${c.get('F')} has no episode in the JSON`)
    assert.equal(c.get('D'), e.line, `sheet row ${r}: the line`)
    assert.equal(c.get('C'), e.episode, `sheet row ${r}: the episode`)
    assert.equal(c.get('B'), e.label, `sheet row ${r}: the sage`)
  }
  const block = rows.slice(titleAt + 1).filter(([, c]) => typeof c.get('F') === 'number')
  assert.deepEqual(block.map(([, c]) => String(c.get('F'))), doc.unresolved.map(u => u.sage))
  for (const [, c] of block) assert.equal(c.get('D'), undefined, 'a line for a link that is not an episode')
  assert.ok(block.every(([, c]) => String(c.get('C')).startsWith('https://spotifycreators-web.app.link/')))
})

test('the instructions sheet tells how to paste, in Hebrew, and carries the channel links of the three languages', () => {
  const text = cellsOf(sheet('הוראות'), 1).map(([, c]) => String(c.get('A') ?? '') + ' ' + String(c.get('B') ?? '')).join('\n')
  for (const word of ['YouTube Studio', 'Spotify for Creators', 'בתחילת התיאור']) assert.ok(text.includes(word), `the instructions lack "${word}"`)
  for (const lang of LANGS) assert.ok(text.includes(`${doc.site}/${lang}?utm_source=`), `no channel link for ${lang}`)
  assert.ok(/[א-ת]/.test(text) && !/claude|sonnet|opus|haiku/i.test(text))
})

